Lemma unsigned_sx32 (w : word) : bv_unsigned w < 2 ^ 32 ->
  bv_unsigned (sx32 w) = (if bv_unsigned w <? 2 ^ 31 then bv_unsigned w else bv_unsigned w + (2 ^ 64 - 2 ^ 32)).
